import{_ as t,o as i,c as h,a5 as c}from"./chunks/framework.CsGesDJn.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"feature/admin-management/3-10-9-deactive-user/report3_spec.md","filePath":"feature/admin-management/3-10-9-deactive-user/report3_spec.md"}'),o={name:"feature/admin-management/3-10-9-deactive-user/report3_spec.md"};function l(g,n,r,e,s,u){return i(),h("div",null,[...n[0]||(n[0]=[c("<p><strong>3.10.9 Deactive User (Xử lý Vi phạm &amp; Tạm khóa Tài khoản)</strong></p><p><strong>Function Trigger</strong></p><p>Bắt đầu khi Quản trị viên (ADMIN) nhấn nút &quot;Xử lý Vi phạm / Tạm khóa&quot; từ hồ sơ chi tiết người dùng (/admin/users/:id).</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: ADMIN. Quản trị viên áp dụng biện pháp chế tài đối với tài khoản vi phạm.</li><li><strong>Purpose</strong>: Gắn cờ đăng bài hoặc xác nhận khóa toàn tài khoản 30 ngày. Đủ 30 ngày tự mở tài khoản và gửi email.</li><li><strong>Interface</strong>: Hộp thoại Xử lý Vi phạm &amp; Chế tài Tài khoản (SCR-ADM-09), gồm tóm tắt thông tin tài khoản, bộ đếm thẻ phạt 30 ngày, 2 lựa chọn hình thức chế tài và ô nhập lý do bắt buộc.</li><li><strong>Data Processing</strong>: RED/ba ORANGE còn hiệu lực tạo yêu cầu xem xét. Admin đọc chứng cứ, xác nhận DEACTIVATE kèm lý do; đặt deactivatedAt/reactivateAt=deactivatedAt+30 ngày, thu hồi mọi session/token và chặn tài khoản. Job nền chạy an toàn khi lặp tự chuyển ACTIVE khi đủ hạn và gửi email; không cần Admin duyệt mở lại.</li></ul><p><strong>Screen Layout</strong></p><p>Figure — Hộp thoại Xử lý Vi phạm &amp; Tạm khóa Người dùng (SCR-ADM-09):</p><ul><li>Left/Header: Tiêu đề &quot;Xử lý Vi phạm &amp; Chế tài Tài khoản&quot;, biểu tượng tam giác cảnh báo màu cam (nếu Gắn cờ) hoặc ổ khóa màu đỏ (nếu Tạm khóa), hiển thị User ID mục tiêu.</li><li>Center: Thông tin user, bộ đếm YELLOW/ORANGE/RED còn hiệu lực, yêu cầu/chứng cứ, chọn FLAG hoặc DEACTIVATE, lý do và checkbox xác nhận. Trước khóa Owner duy nhất, nêu thành viên vẫn làm việc trong quyền hiện có, thao tác riêng Owner tạm dừng. Hiện lúc bắt đầu khóa, lúc tự mở và trạng thái xem xét.</li><li>Buttons: Nút &quot;Hủy bỏ&quot;, Nút hành động chính (Màu cam &quot;Xác nhận Gắn cờ&quot; hoặc Màu đỏ &quot;Xác nhận Tạm khóa&quot;).</li><li>Footer: Quy tắc bắt buộc: &quot;Quản trị viên không thể tự xử lý chính mình và không thể xử lý Admin khác. Toàn bộ bài viết và dữ liệu thanh toán PayOS được bảo toàn nguyên vẹn trong CSDL&quot;.</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: userId, sanctionType (FLAG/DEACTIVATE), reason; DEACTIVATE cần Admin xác nhận rõ và chứng cứ xem xét.</li><li><strong>Input optional</strong>: sanctionRequestId, linkedStrikeIds, tham chiếu chứng cứ.</li><li><strong>System data</strong>: adminId, systemRole/status đối tượng, thẻ hiệu lực, trạng thái xem xét, deactivatedAt, reactivateAt, restoredAt, tình trạng gửi email.</li><li><strong>Output</strong>: Kết quả chế tài { userId, status: &quot;FLAGGED&quot; | &quot;DEACTIVATED&quot;, activeStrikes } kèm mã HTTP 200 OK.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li><strong>BR-63</strong>: Chỉ ADMIN xác nhận khóa tài khoản. RED hoặc ba ORANGE còn hiệu lực tạo yêu cầu chờ xem xét, không tự khóa. Kiểm tra lại chứng cứ khi xác nhận; yêu cầu cũ/lặp không tạo xử phạt trùng.</li><li><strong>BR-94</strong>: FLAGGED vẫn đăng nhập nhưng cả bài mới và đã lên lịch phải được ADMIN duyệt. DEACTIVATED khóa toàn tài khoản 30 ngày từ lúc xác nhận xử phạt.</li><li><strong>BR-06</strong>: Áp dụng DEACTIVATED ở đăng nhập, refresh và thao tác đã xác thực; token phát trước đó không được giữ quyền truy cập.</li><li><strong>BR-22</strong>: Thu hồi mọi session và access/refresh token khi khóa. Mở lại phải đăng nhập mới; token đã thu hồi không có hiệu lực trở lại.</li><li><strong>BR-23</strong>: Owner duy nhất của Agency/Workspace vẫn được sửa hồ sơ, ghi strike, gắn cờ và khóa tài khoản 30 ngày sau xác nhận. Thành viên khác tiếp tục quyền hiện có; thao tác chỉ Owner được làm tạm dừng đến khi mở khóa. Không khóa cả Agency, không tự chuyển quyền sở hữu. Quyền Owner độc lập với system role.</li><li><strong>BR-35</strong>: Admin không tự xử phạt hoặc xử phạt ADMIN ngang hàng.</li><li><strong>BR-96</strong>: Đến reactivateAt tự chuyển ACTIVE và gửi email mở lại, không cần Admin duyệt. Dọn thẻ không mở khóa sớm. Giữ lịch sử thẻ; hết phạt không hồi sinh thẻ cũ. Email lỗi được retry mà không hoàn tác mở khóa. Không mở DELETED hoặc SUSPENDED cũ không thuộc xử phạt này.</li><li><strong>BR-92</strong>: Giữ toàn bộ dữ liệu user, Agency, bài viết và thanh toán; không xóa cứng.</li><li><strong>BR-16</strong>: Audit xem xét, xác nhận, thu hồi session và tự mở với chứng cứ/thời điểm liên kết.</li></ul></li><li><p><strong>Validation</strong></p><ul><li>Thiếu ADMIN, tự phạt hoặc phạt Admin ngang hàng → MSG39.</li><li>Không có user/yêu cầu → MSG38; thiếu lý do/xác nhận → MSG02.</li><li>Owner duy nhất được khóa sau thông báo ảnh hưởng và Admin xác nhận; không từ chối MSG92 chỉ vì là Owner.</li><li>Yêu cầu đã xử lý hoặc tài khoản đã khóa → xung đột/kết quả đã có; không vô tình tính lại thời hạn phạt.</li><li>Khóa thành công → MSG91.</li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ol><li>RED/ba ORANGE còn hiệu lực mở yêu cầu xem xét; chưa tự khóa tài khoản.</li><li>Admin đọc thẻ/chứng cứ rồi chọn FLAG hoặc xác nhận DEACTIVATE kèm lý do.</li><li>Kiểm tra bảo vệ bản thân/ngang hàng và trạng thái hiện tại; hiển thị ảnh hưởng Owner duy nhất nếu có.</li><li>Áp dụng xử phạt đúng một lần. DEACTIVATE lưu hạn 30 ngày, thu hồi mọi session/token, gửi email xử phạt và audit.</li><li>Đến hạn, job nền kiểm tra đúng xử phạt đã đủ thời gian và tự chuyển ACTIVE.</li><li>Ghi sự kiện mở lại, gửi email; user đăng nhập lại bằng session mới.</li></ol></li><li><p><strong>Abnormal Cases</strong></p><ul><li>2.a1: Admin chưa xác nhận → yêu cầu chưa giải quyết; không khóa.</li><li>3.a1: Đối tượng bản thân/Admin ngang hàng → MSG39; chỉ riêng quyền Owner không làm từ chối.</li><li>4.a1: Gửi yêu cầu lặp → trả kết quả cũ; không tạo thẻ trùng hoặc tính lại hạn phạt.</li><li>5.a1: Worker gián đoạn → xử lý bù các hạn đã tới khi phục hồi; không mở trước hạn.</li><li>6.a1: Email lỗi → retry thông báo, tài khoản vẫn đã mở. Không ghi đè xử phạt khác hoặc trạng thái DELETED hiện tại.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>User FLAGGED giữ session nhưng đăng bài qua ADMIN; user DEACTIVATED mất toàn bộ quyền truy cập tài khoản.</li><li>Lưu hạn phạt 30 ngày; đủ hạn tự ACTIVE, có email và audit.</li><li>Thành viên Agency tiếp tục quyền hiện có; không tự chuyển Owner hoặc khóa toàn Agency.</li><li>Giữ toàn bộ dữ liệu và lịch sử xử phạt/strike.</li></ul>",14)])])}const p=t(o,[["render",l]]);export{m as __pageData,p as default};
